local _, ns = ...
if ns.LOCALE ~= "esES" and ns.LOCALE ~= "esMX" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/esES.lua.
L["WN29_1_TITLE"] = "Una ventana de Legado clásica"
L["WN29_1_TEXT"] = "El botón y la tecla de Legado abren una ventana de Legado clásica: el camino de recompensas y los desafíos en las antiguas barras de habilidad, con búsqueda y filtro, y los árboles de Legado en la antigua ventana de talentos. Activada por defecto; desactívala en las opciones (/fcui), en Personaje y hechizos."
L["WN29_2_TITLE"] = "Tus propios diseños siguen siendo tuyos"
L["WN29_2_TEXT"] = "Con el addon desactivado, las barras de acción de tus propios diseños del modo Edición ya no quedan en los sitios de la barra clásica. Los sitios guardados ahí antes se devuelven la próxima vez que pulses Recargar IU en las opciones (/fcui) o escribas /fcui off."
L["WN29_3_TITLE"] = "Correcciones"
L["WN29_3_TEXT"] = "/fcui off vuelve a desactivar el addon. Hacer clic en un miembro de la hermandad en combate abre sus detalles. La ventana de opciones del juego ya no se llena de errores tras un combate, los niveles de misión siguen ocultos con la opción desactivada y la flecha para bajar del chat ya no parpadea."
L["WN29_4_TITLE"] = "Huecos de arma"
L["WN29_4_TEXT"] = "Los huecos de arma de la ventana del personaje quedan centrados sobre dos marcos, sin el marco vacío del hueco a distancia."
L["WN28_1_TITLE"] = "Aliados recientes e Ignorar"
L["WN28_1_TEXT"] = "La pestaña Amigos de la ventana social tiene las pestañas Aliados recientes e Ignorar junto a Amigos. Aliados recientes muestra los jugadores con los que te agrupaste hace poco y tiene una línea de búsqueda; Ignorar muestra los jugadores que ignoras."
L["WN28_2_TITLE"] = "De nuevo la ventana social clásica"
L["WN28_2_TEXT"] = "Tras la última actualización del juego, O y el botón de hermandad abrían la nueva ventana social del juego. Vuelven a abrir la clásica, sus pestañas se alinean y la pestaña de banda ha vuelto."
L["WN28_3_TITLE"] = "Correcciones tras la actualización del juego"
L["WN28_3_TEXT"] = "Los puntos de combo vuelven a mostrar los cinco orbes clásicos. La franja oscura sobre el modelo del personaje y el recuadro oscuro en las páginas de anuncios del buscador de grupo han desaparecido, el botón de ordenar funciona en el modo de una bolsa, y el buscador de grupo ya no salta al abrirlo en combate."
L["WN28_4_TITLE"] = "Ventana de botín y bolsas"
L["WN28_4_TEXT"] = "Con Ventana de botín desactivada, la ventana de botín del juego ya no muestra dos cuadrados blancos en sus esquinas. El botón de ordenar de las bolsas cabe junto al cuadro de búsqueda."
L["WN27_1_TITLE"] = "Menos trabajo en segundo plano"
L["WN27_1_TEXT"] = "Las placas de nombre solo se vuelven a colocar cuando cambia un ajuste de las placas, no con cada ajuste que cambie el juego u otro addon. Las coordenadas del minimapa solo se miden cuando cambian. Nada se ve distinto."
L["WN26_1_TITLE"] ="Colores de clase por marco"
L["WN26_1_TEXT"] = "Salud con color de clase y Recuadro de nombre con color de clase están desactivadas por defecto; actívalas en las opciones (/fcui), en Marcos de unidad. Cada una tiene ahora debajo un desplegable de marcos: Jugador, Objetivo y Foco, así el objetivo puede llevar su color de clase mientras tu propio marco sigue como estaba."
L["WN26_2_TITLE"] = "Color del recuadro de nombre"
L["WN26_2_TEXT"] = "Un nuevo desplegable Color del recuadro de nombre, en Marcos de unidad, elige en qué marcos el recuadro de nombre toma el color del juego para la unidad (azul para un jugador amistoso). Objetivo y Foco están marcados, como en Classic Era; desmarca uno para un recuadro sin color. Jugador está desactivado por defecto; actívalo en las opciones (/fcui) para colorear el tuyo."
L["WN26_3_TITLE"] = "Correcciones"
L["WN26_3_TEXT"] = "Con la barra de salud gruesa sobre el nombre, el recuadro de nombre del marco del jugador ya no se ve detrás de la barra. Al desmarcar el recuadro de nombre con color de clase, el color desaparece del objetivo y del foco al instante."
L["WN25_1_TITLE"] = "Grifos"
L["WN25_1_TEXT"] = "Los grifos se guardan ahora con el diseño del modo de edición, como las piezas propias del juego: cada diseño conserva sus propios lugares para ellos, y Guardar en un diseño predefinido del juego pide un diseño nuevo, que los recibe. Un movimiento sin guardar se descarta al cerrar el modo de edición. El diseño clásico de las opciones los devuelve a los extremos de la barra."
L["WN24_1_TITLE"] = "Bolsas"
L["WN24_1_TEXT"] = "Las bolsas abiertas ya no saltan hacia un lado al equipar un objeto con clic derecho, ni en combate ni fuera de él."
L["WN23_1_TITLE"] = "Temporizadores de golpe"
L["WN23_1_TEXT"] = "Cambiar de arma en combate ya no provoca un error de Lua en cada fotograma en que se muestra la barra de golpe, y el destello al golpear sigue funcionando tras el cambio."
L["WN22_1_TITLE"] = "Profesiones"
L["WN22_1_TEXT"] = "Una profesión se abre en la ventana clásica de habilidades comerciales, y el libro de profesiones es el antiguo y pequeño, en el marco del libro de hechizos. El botón de tamaño junto al de cerrar cambia cualquiera de los dos a la ventana completa del juego."
L["WN22_2_TITLE"] = "Libro de hechizos y talentos"
L["WN22_2_TEXT"] = "Un botón de Libro de hechizos en el micromenú, junto a Personaje, abre el libro de hechizos clásico. La ventana de talentos del juego lleva el marco clásico, y el botón de Talentos la abre siempre en tus talentos."
L["WN22_3_TITLE"] = "Micromenú y minimapa"
L["WN22_3_TEXT"] = "Logros, Guía de aventuras y Vivienda salen del micromenú, pues 1.x no los tenía, y cada uno tiene un icono en el minimapa. Para recuperar un botón, desmárcalo en Ocultar microbotones en las opciones (/fcui)."
L["WN22_4_TITLE"] = "Unión rápida"
L["WN22_4_TEXT"] = "Unión rápida ha dejado la fila de pestañas de la ventana social. Abre Amigos y luego Aliados recientes: la pestaña Unión rápida bajo la lista cambia a ella, y la pestaña Aliados recientes vuelve."
L["WN22_5_TITLE"] = "Rendimiento"
L["WN22_5_TEXT"] = "Los temas de color usan mucha menos CPU: el arte coloreado sigue al del juego solo cuando algo cambia, no en cada fotograma. Los menús de clic derecho de los retratos, las bolsas y las ventanas se abren sin tirones."
L["WN22_6_TITLE"] = "Macros"
L["WN22_6_TEXT"] = "Un hechizo llevado con Mayús-clic del libro de hechizos clásico a una macro entra con su nombre y rango, como desde el libro del juego; antes entraba como un enlace de chat, que una macro no puede lanzar. La ventana de macros tiene las pestañas de Classic Era."
L["WN22_7_TITLE"] = "Macros"
L["WN22_7_TEXT"] = "Un hechizo llevado con Mayús-clic del libro de hechizos clásico a una macro entra con su nombre y rango, como desde el libro del juego; antes entraba como un enlace de chat, que una macro no puede lanzar. Los talentos también entran con su nombre. La ventana de macros tiene las pestañas de Classic Era."
L["WN22_8_TITLE"] = "Menús desplegables"
L["WN22_8_TEXT"] = "Los menús desplegables del juego, como el menú de estado (Disponible, Ausente, Ocupado) y el menú de rastreo del minimapa, tienen ahora el marco de hierro de Classic Era, que contiene sus iconos y flechas."
L["WN22_9_TITLE"] = "Reputación y monedas"
L["WN22_9_TEXT"] = "Ambas pestañas conservan las filas clásicas: espaciado uniforme, los encabezados antiguos, una sola columna de barras. Un grupo de facciones tiene su botón de más o menos con sus facciones sangradas debajo, y el filtro es un pequeño botón de flecha arriba a la derecha."
L["WN22_10_TITLE"] = "Otras correcciones"
L["WN22_10_TEXT"] = "Las pestañas bajo una ventana se quedan en su borde inferior; con algunos tamaños de interfaz subían. Mayús-clic en una profesión deja abierto el libro de hechizos, los números de maná de un druida en sus formas siguen el ajuste Texto de estado del juego, y la pestaña Ayuda muestra solo las preguntas de la versión del juego que juegas."
L["WN22_11_TITLE"] = "Ventanas en Retail"
L["WN22_11_TEXT"] = "La bolsa de componentes queda libre de la barra de latencia, la ventana de personaje no tiene líneas finas alrededor del modelo, la ventana social tiene una sola pestaña Quién, y los bordes de las ventanas quedan como en Forever."
L["WN21_1_TITLE"] = "Lista de hermandad"
L["WN21_1_TEXT"] = "Al hacer clic en un miembro se abren sus notas y opciones con todos los miembros; en hermandades grandes, con muchos no se abría nada. La lista también usa mucha menos CPU mientras está abierta."
L["WN21_2_TITLE"] = "Compartir misiones"
L["WN21_2_TEXT"] = "Compartir misión en el registro de misiones clásico funciona con cualquier misión con una sola pulsación, también justo después de entrar al juego. Solo funcionaba con las misiones de la zona que el mapa del mundo había mostrado por última vez."
L["WN21_3_TITLE"] = "Ventanas"
L["WN21_3_TEXT"] = "Una carta abierta tiene el marco de ventana clásico, como la bandeja de entrada, y el panel lateral de la ventana del personaje ya no muestra una fina línea transparente con algunos tamaños de interfaz."
L["WN20_1_TITLE"] ="Detalles de rango JcJ"
L["WN20_1_TEXT"] = "La pestaña JcJ de la ventana del personaje puede mostrar los detalles de tu rango y las recompensas del siguiente. Haz clic en la flecha de abajo a la derecha de la pestaña para abrir el panel lateral."
L["WN20_2_TITLE"] = "Bolsa de botones de addons"
L["WN20_2_TEXT"] = "Su lugar por defecto está ahora a la izquierda del reloj, lejos del ojo del buscador de grupos, y deja en el minimapa nuestros propios iconos, como Legado. El botón Diseño clásico también devuelve a su sitio los botones del minimapa que hayas movido."
L["WN20_3_TITLE"] = "Otros addons"
L["WN20_3_TEXT"] = "Las partes de ClassicUI Forever que desactivas ya no tocan los marcos del juego, así que los addons que los cambian conservan su aspecto."
L["WN19_1_TITLE"] = "Iconos del minimapa"
L["WN19_1_TEXT"] = "Cualquier botón del micromenú puede ir ahora en el minimapa como icono: márcalo en Botones del micromenú en el minimapa, en las opciones (/fcui). Legado y el buscador de grupos están activados por defecto, así Legado vuelve a tener acceso. Mantén Mayús y arrastra para mover nuestros botones del minimapa por el anillo."
L["WN19_2_TITLE"] = "Seguimiento de misiones"
L["WN19_2_TEXT"] = "El seguimiento de objetivos puede ser el seguimiento de misiones sencillo de Classic Era. Desactivado por defecto; para activarlo, pon Seguimiento de objetivos en el de Classic Era en las opciones (/fcui), en Misiones. Clic en un título para abrir la misión, Mayús-clic para dejar de seguirla, clic derecho para más."
L["WN19_3_TITLE"] = "Ventana de opciones"
L["WN19_3_TEXT"] = "La ventana de opciones es más grande y sus listas largas son ahora desplegables, así hay menos que desplazar."
L["WN19_4_TITLE"] = "Porcentaje de amenaza"
L["WN19_4_TEXT"] = "El porcentaje de amenaza puede mostrarse solo en grupo o mazmorra: activa Solo en grupo o mazmorra en las opciones (/fcui), en Marcos de unidad. Desactivado por defecto."
L["WN19_5_TITLE"] = "Detalles de Classic Era"
L["WN19_5_TEXT"] = "La descripción emergente del botón del menú del juego tiene las descripciones de Classic Era, los menús desplegables usan el marco de hierro de Classic Era y los botones del micromenú ya no se vuelven grises con el menú del juego abierto."
L["WN19_6_TITLE"] = "Correcciones"
L["WN19_6_TEXT"] = "Restablecer opciones mantiene las barras de tamaño clásico, los temas personalizados colorean por completo las pestañas de las opciones, el arte de la barra clásica sigue visible en el diseño ClassicUI Forever, el botón de opciones ya no tapa la lupa de rastreo y, con Minimapa desmarcado, los iconos del minimapa ocultados por otro addon siguen ocultos."
L["WN18_1_TITLE"] = "Profesiones"
L["WN18_1_TEXT"] = "La ventana de profesión ahora puede seguir una receta (sus componentes aparecen en el rastreador de objetivos), filtrar por ranura de equipo y enlazar tu profesión en el chat con el eslabón junto a su título. La tecla de profesiones vuelve a abrir el libro de profesiones."
L["WN18_2_TITLE"] = "Dragones de élite"
L["WN18_2_TEXT"] = "Los enemigos de élite pueden mostrar un dragón dorado alrededor de su nivel en la placa de nombre, y los raros uno plateado: activa Dragones de élite en las opciones (/fcui), en Placas de nombre. Con un tema personalizado, Ignorar el tema en los marcos de élite e Ignorar el tema en los dragones de las placas, en Tema personalizado, mantienen los dragones dorados y plateados. Todo desactivado por defecto."
L["WN18_3_TITLE"] = "Brillo de combate"
L["WN18_3_TEXT"] = "Para quitar el pulso rojo del marco del jugador mientras atacas, activa Ocultar brillo de combate en las opciones (/fcui), en Marcos de unidad. Desactivado por defecto."
L["WN18_4_TITLE"] = "Barras de lanzamiento"
L["WN18_4_TEXT"] = "Los hechizos interrumpidos del objetivo, el foco y las placas de nombre ahora se vuelven rojos y solo dicen Interrumpido, como en Classic Era. Para ver quién interrumpió, activa Nombrar a quien interrumpe en las opciones (/fcui), en Barras de lanzamiento. Las canalizaciones se ven en verde."
L["WN18_5_TITLE"] = "Dificultad de instancia"
L["WN18_5_TEXT"] = "La bandera de dificultad que el juego muestra en el minimapa en mazmorras y bandas ahora está oculta. Para recuperarla, elige visible o al pasar el ratón en Minimapa, en las opciones (/fcui)."
L["WN18_6_TITLE"] = "Diseño clásico"
L["WN18_6_TEXT"] = "La figura de durabilidad ya no queda oculta tras las barras laterales, y los beneficios se colocan en los sitios de Classic Era junto al minimapa. El diseño también ofrece el tamaño de interfaz de Classic Era cuando el tuyo es distinto."
L["WN18_7_TITLE"] = "Aspecto"
L["WN18_7_TEXT"] = "Los menús tienen el fondo negro de Classic Era, y las placas de nombre tienen el tamaño de Classic Era. La parte vacía de las barras de experiencia y reputación está sombreada como en Classic Era; para quitar la sombra, desmarca Barras de experiencia y reputación sombreadas en Barra clásica."
L["WN18_8_TITLE"] = "Correcciones"
L["WN18_8_TEXT"] = "Entrenar funciona con recetas muy abajo en la lista de un instructor. Los botones del chat se quedan en todas las pestañas del chat, y Mayús-clic enlaza un talento en el chat. El mapa del mundo abierto en combate ya no captura clics, y los botones rojos del modo de edición se mantienen enteros al cambiar de tema."
L["WN17_1_TITLE"] = "Errores en placas de nombre"
L["WN17_1_TEXT"] = "Con un tema activo, las placas de nombre clásicas ya no causan mensajes de error."
L["WN17_2_TITLE"] = "Beneficios del objetivo"
L["WN17_2_TEXT"] = "Los beneficios bajo los marcos del objetivo y del foco aparecen ahora en su sitio al cambiar de objetivo, sin el breve salto."
L["WN17_3_TITLE"] = "Mapa del mundo en combate"
L["WN17_3_TEXT"] = "El mapa del mundo clásico abierto en combate se ve ahora igual que fuera de combate."
L["WN16_1_TITLE"] = "Iconos de acción"
L["WN16_1_TEXT"] = "Con un tema activo, los iconos de los botones de acción ya no se oscurecen al azar."
L["WN16_2_TITLE"] = "Brillo de combate"
L["WN16_2_TEXT"] = "Con Barras de salud gruesas sobre el nombre, el brillo rojo de combate y el dorado de descanso rodean ahora todo el marco del jugador en lugar de la barra de salud. Las Barras de salud gruesas están desactivadas por defecto; actívalas en las opciones (/fcui), en Marcos de unidad."
L["WN16_3_TITLE"] = "Placas de nombre"
L["WN16_3_TEXT"] = "Con las placas de nombre clásicas desactivadas, las placas de nombre del juego ya no causan mensajes de error."
L["WN15_1_TITLE"] = "Amenaza"
L["WN15_1_TEXT"] = "El porcentaje de amenaza de Classic Era aparece ahora sobre los marcos del objetivo y del foco en combate. El brillo rojo alrededor de los marcos de unidad queda oculto por defecto; para recuperarlo, desmarca Ocultar brillo de amenaza en las opciones (/fcui), en Marcos de unidad."
L["WN15_2_TITLE"] = "Maná de druida"
L["WN15_2_TEXT"] = "En forma de oso y de felino, los druidas ven ahora su maná en una barra pequeña bajo la barra de ira o de energía."
L["WN15_3_TITLE"] = "Color de salud enemiga"
L["WN15_3_TEXT"] = "Desactivado por defecto. Para usarlo, activa Barras de salud gruesas en las opciones (/fcui), en Marcos de unidad, y elige Según reacción en Salud enemiga: los enemigos neutrales tienen la barra amarilla y los hostiles, roja."
L["WN15_4_TITLE"] = "Texto en inglés"
L["WN15_4_TEXT"] = "Para un juego en otro idioma: los textos propios de este addon pueden mostrarse en inglés, parte por parte. Desactivado por defecto; actívalo en las opciones (/fcui), en Otros, Texto en inglés."
L["WN15_5_TITLE"] = "Lista Quién"
L["WN15_5_TEXT"] = "La flecha de arriba de la última columna de la Lista Quién incluye ahora los filtros de clase, raza y zona del juego. Una búsqueda con uno o dos resultados se queda en la ventana en lugar de ir al chat."
L["WN15_6_TITLE"] = "Color plano"
L["WN15_6_TEXT"] = "Color plano pinta el arte de ventanas y barras en un solo color liso en lugar de metal. Ahora mantiene las líneas finas dentro de las ventanas, alrededor de listas, pies y separadores, salvo que actives también Ocultar bordes internos. Ambos están desactivados por defecto: activa Tema personalizado y luego Color plano en las opciones (/fcui), en Aspecto."
L["WN15_7_TITLE"] = "Temporizadores de golpe"
L["WN15_7_TEXT"] = "Los temporizadores de golpe pueden funcionar ahora sin el destello tras cada golpe: desmarca Destello al golpear en las opciones (/fcui), en Temporizadores de golpe."
L["WN15_8_TITLE"] = "Placas de nombre"
L["WN15_8_TEXT"] = "Los nombres y números pequeños de las placas de nombre usan ahora el texto sencillo de Classic Era. Nuevo y desactivado por defecto: Mismo tamaño cerca y lejos mantiene todas las placas del mismo tamaño, como en Classic Era; actívalo en las opciones (/fcui), en Placas de nombre."
L["WN15_9_TITLE"] = "Ventanas"
L["WN15_9_TEXT"] = "Las ventanas de misión, de diálogo y del vendedor y la lista del registro de misiones tienen ahora el borde fino de Classic Era alrededor de su contenido, y la ventana del personaje muestra la cara de tu personaje en todas las pestañas."
L["WN15_10_TITLE"] = "Correcciones"
L["WN15_10_TEXT"] = "Con un tema activo, los bordes de iconos, los anillos de retrato, los menús y las flechas de página del vendedor toman su color, y los controles deslizantes siguen visibles. Las pestañas de la ventana del personaje responden ahora donde se dibujan."
L["WN14_1_TITLE"] = "Mando"
L["WN14_1_TEXT"] = "Con la interfaz de mando activa, el libro de hechizos clásico, los talentos y el registro de misiones se abren dentro de las ventanas del propio juego, para que un mando pueda moverse por ellos."
L["WN14_2_TITLE"] = "Tema en todo"
L["WN14_2_TEXT"] = "Con un tema activo, las piezas del propio juego también toman su color donde dejaste desactivadas las clásicas: minimapa, marcos de unidad, barras, ventanas y los botones del menú del juego."
L["WN14_3_TITLE"] = "Oscuridad"
L["WN14_3_TEXT"] = "Oscuro tiene un deslizador de gris claro a negro, con un botón para volver al valor predeterminado."
L["WN14_4_TITLE"] = "Color plano"
L["WN14_4_TEXT"] = "Color plano (Tema personalizado) muestra las partes que marques en un solo color plano, con las mismas formas."
L["WN14_5_TITLE"] = "Microbotones"
L["WN14_5_TEXT"] = "Ocultar microbotones ahora funciona en el micromenú del propio juego con la barra clásica desactivada, y puede ocultar la tienda."
L["WN14_6_TITLE"] = "Barras 6 a 8"
L["WN14_6_TEXT"] = "Ocultar barras 6 a 8 ya no existe: deciden los ajustes de barras de acción del propio juego."
L["WN14_7_TITLE"] = "Correcciones"
L["WN14_7_TEXT"] = "Coordenadas: ocultas y al pasar el ratón funcionan con el minimapa del juego, los botones de minimapa de otros accesorios toman el tema, y la mochila de un cazador muestra las casillas libres en lugar de la munición."
L["WN13_1_TITLE"] = "Brillo de amenaza"
L["WN13_1_TEXT"] = "Ocultar brillo de amenaza (Marcos de unidad) quita el brillo rojo de amenaza de los marcos de unidad. El número de amenaza del juego se mantiene."
L["WN13_2_TITLE"] = "Objetos de misión"
L["WN13_2_TEXT"] = "Objetos de misión sencillos (Ventanas de bolsa) muestra los objetos de misión de las bolsas y el banco sin el borde de misión."
L["WN13_3_TITLE"] = "Números"
L["WN13_3_TEXT"] = "Números sin separadores (Marcos de unidad) quita los separadores de miles de los números grandes, en las barras y en todo el juego."
L["WN13_4_TITLE"] = "Iconos de acción"
L["WN13_4_TEXT"] = "Con un tema activo, los iconos de acción vuelven a verse enteros, como en Classic Era; solo su propio borde toma el color del tema."
L["WN13_5_TITLE"] = "Tus barras"
L["WN13_5_TEXT"] = "Si la 0.14.0 cambió tus barras, una línea de chat al entrar te deja devolverlas a como estaban o elegir el aspecto clásico."
L["WN13_6_TITLE"] = "Ventana social"
L["WN13_6_TEXT"] = "Las pestañas Amigos y Banda van en su borde fino como en Classic Era, y la descripción de la pestaña Banda vuelve a verse fuera de una banda."
L["WN13_7_TITLE"] = "Correcciones"
L["WN13_7_TEXT"] = "El botín en el ratón se abre con el primer objeto bajo el cursor, las etiquetas de las pestañas se vuelven blancas al pasar el ratón, y Diseño clásico devuelve el micromenú y las casillas de bolsa clásicos."
L["WN12_1_TITLE"] = "Ventanas"
L["WN12_1_TEXT"] = "Junto al botón de cerrar de cada ventana hay un candado y un reinicio: desbloqueada, la ventana se arrastra por su título. Las ventanas de misión y de diálogo, la ventana social, el buscador de grupos y el libro de profesiones se colocan y se ajustan en Ventanas de ClassicUI Forever."
L["WN12_2_TITLE"] = "Temporizadores de golpe"
L["WN12_2_TEXT"] = "Los temporizadores de golpe del juego con el aspecto de la barra de lanzamiento 1.x, un color por mano y un destello en cada golpe. Los colores y el Grosor del borde se eligen en las opciones."
L["WN12_3_TITLE"] = "Barras de salud gruesas"
L["WN12_3_TEXT"] = "Una barra de salud más alta en los marcos de jugador, objetivo y foco, sobre el nombre o sobre el maná (Marcos de unidad). Recuadro de nombre con color de clase y Tamaño de nombres también son nuevos ahí."
L["WN12_4_TITLE"] = "Grifos"
L["WN12_4_TEXT"] = "Los grifos se arrastran, se ajustan o se ocultan en el modo de edición del juego. Con el ajuste activado se alinean con las barras y vuelven a su sitio."
L["WN12_5_TITLE"] = "Medidor de daño"
L["WN12_5_TEXT"] = "El medidor de daño en el marco 1.x, con botones clásicos y un fondo de mármol o de árbol de talentos que se puede mover."
L["WN12_6_TITLE"] = "Idiomas"
L["WN12_6_TEXT"] = "ClassicUI Forever ya está en alemán, francés, español e italiano."
L["WN12_7_TITLE"] = "Opciones"
L["WN12_7_TEXT"] = "Nuevas pestañas Preguntas y Apoyo, un Color personalizado para el tema y una búsqueda que encuentra un ajuste por más nombres."
L["WN12_8_TITLE"] = "Recursos"
L["WN12_8_TEXT"] = "La visualización personal de recursos en barras 1.x con el antiguo borde de placa de nombre, con el ajuste Separación de barras."
L["WN12_9_TITLE"] = "Barra clásica"
L["WN12_9_TEXT"] = "Casillas de bolsa de tamaño clásico, cualquier microbotón se puede ocultar, el botón de Ayuda vuelve al final del micromenú y La franja sostiene las barras 2 y 3 mantiene esas barras en la franja."
L["WN12_10_TITLE"] = "Minimapa y chat"
L["WN12_10_TEXT"] = "Coordenadas, y un borde y una cabecera que se pueden ocultar en el minimapa, el ojo del buscador de grupos en él cuando su microbotón está oculto, y cada botón del chat se oculta por separado."
L["WN12_11_TITLE"] = "Correcciones"
L["WN12_11_TEXT"] = "Las barras ya no saltan a lo alto de la pantalla tras arrastrarlas en el modo de edición, la barra 1 se mueve con las flechas en el modo de edición, la barra de experiencia ya no sale doble al entrar en combate y las páginas de botín ya no repiten objetos."
L["WN12_12_TITLE"] = "Correcciones menores"
L["WN12_12_TEXT"] = "Los números de mascota y de grupo caben en sus barras, el micromenú ya no salta al arrastrarlo, la barra de latencia conserva su marco y las ayudas de los microbotones salen una vez y con el límite de misiones correcto."
L["WN11_1_TITLE"] = "Chat"
L["WN11_1_TEXT"] = "Ocultar botones de chat permite que el chat quede en el borde de la pantalla, y Barra de desplazamiento del chat mantiene la de WoW Forever (Botones de chat)."
L["WN11_2_TITLE"] = "Niveles de misión"
L["WN11_2_TEXT"] = "Niveles de misión (Misiones) muestra el nivel de cada misión en el mapa, en el seguimiento y en el registro de misiones, en sintonía con el filtro propio del mapa."
L["WN11_3_TITLE"] = "Tema oscuro"
L["WN11_3_TEXT"] = "Los menús de clic derecho, los botones de minimapa de accesorios, los botones de zoom, el reloj y el icono de día y noche toman el tema, y los iconos de acción no muestran borde claro."
L["WN11_4_TITLE"] = "Correcciones"
L["WN11_4_TEXT"] = "Sin nivel de misión duplicado en el seguimiento, sin errores de los menús de clic derecho en mazmorras, y el menú del objetivo se queda en pantalla."
L["WN10_1_TITLE"] = "Minimapa"
L["WN10_1_TEXT"] = "Cada parte del minimapa puede mostrarse, mostrarse solo al pasar el ratón u ocultarse (Minimapa en las opciones), y acercar y alejar se mueven cada uno por el anillo en Ventanas de ClassicUI Forever."
L["WN10_2_TITLE"] = "Micromenú"
L["WN10_2_TEXT"] = "Las descripciones de Classic Era en las descripciones de los microbotones, y Ocultar microbotones quita botones sueltos del menú (Barra clásica)."
L["WN10_3_TITLE"] = "Llavero"
L["WN10_3_TEXT"] = "Se abre aunque no tenga llaves, en su propia ventana, con el arte de Classic Era."
L["WN10_4_TITLE"] = "Nuevas opciones"
L["WN10_4_TEXT"] = "Ocultar barra de actitud (Barra clásica), Tamaño del texto del nombre (Placas de nombre) y Descripción de unidad en las barras (Marcos de unidad)."
L["WN10_5_TITLE"] = "Correcciones"
L["WN10_5_TEXT"] = "Las flechas de desplazamiento se vuelven grises cuando no hay nada que desplazar, el registro de misiones resalta como en Classic Era, Última conexión de la hermandad ordena bien y la ventana de macros se abre junto al libro de hechizos."
L["WN10_6_TITLE"] = "Correcciones menores"
L["WN10_6_TEXT"] = "Las flechas de talentos, la pestaña de hermandad sin hermandad, las flechas de página sobre el mapa, la bolsa de botones de accesorios y avisos de diseño más cortos."
L["WN9_1_TITLE"] = "Mapa del mundo clásico"
L["WN9_1_TEXT"] = "El mapa pequeño de Classic Era, con la lista de misiones del mapa en su propio panel al lado y las recompensas tras el texto de la misión. Barra de navegación del mapa en Mapa de las opciones devuelve el diseño de mapa del juego."
L["WN9_2_TITLE"] = "Nuevas opciones"
L["WN9_2_TEXT"] = "Ocultar botón de misiones del mapa (Mapa), Barras de tamaño clásico (Barra clásica) y Sacudida al interrumpir (Barras de lanzamiento)."
L["WN9_3_TITLE"] = "Estilo clásico"
L["WN9_3_TEXT"] = "Los menús de clic derecho, los desplegables, la ventana social, el buscador de grupos, la lista Quién y la lista de la hermandad siguen a Classic Era; la ventana de opciones toma el aspecto del cliente actual de Classic Era, y la lista de ignorados y el probador el estilo clásico."
L["WN9_4_TITLE"] = "Modo edición"
L["WN9_4_TEXT"] = "El libro de hechizos se puede mover y redimensionar en Ventanas de ClassicUI Forever."
L["WN9_5_TITLE"] = "Barras y seguimiento"
L["WN9_5_TEXT"] = "Las barras 4 y 5 mantienen su sitio en el borde de la pantalla, y el seguimiento de misiones ya no se pone encima de ellas."
L["WN9_6_TITLE"] = "Correcciones"
L["WN9_6_TEXT"] = "Los PNJ neutrales muestran su nivel en lugar de una calavera, y hacer clic en las barras de un marco de unidad vuelve a seleccionar objetivo."
L["WN9_7_TITLE"] = "Ventanas y pestañas"
L["WN9_7_TEXT"] = "Las ventanas de vendedor, correo, cédula de hermandad y tabardo, y muchas otras ventanas y pestañas, se alinean con Classic Era; Escape cierra la ventana de cédula de hermandad."
L["WN8_1_TITLE"] = "Grifos sobre las barras"
L["WN8_1_TEXT"] = "Marca Grifos sobre las barras en Barra clásica de las opciones para dibujar los grifos delante de las barras 2 y 3."
L["WN8_2_TITLE"] = "Ventanas que abren al pulsar"
L["WN8_2_TEXT"] = "Las teclas del libro de hechizos, profesiones, talentos, hermandad y registro de misiones y Escape actúan al pulsar, como las ventanas propias del juego."
L["WN8_3_TITLE"] = "Correcciones"
L["WN8_3_TEXT"] = "Los hechizos se vuelven a arrastrar a la barra de acción 1, el nombre de zona se centra en la barra del minimapa esté donde esté el calendario, y las pestañas y órdenes de mascota del libro de hechizos se ven bien."
L["WN7_1_TITLE"] = "Texto de teclas clásico"
L["WN7_1_TEXT"] = "Los nombres de teclas en los botones de acción tienen el tamaño y el contorno de Classic Era. Tamaño del texto de teclas en Estilo de botones de las opciones los agranda o los reduce."
L["WN7_2_TITLE"] = "Sitios del calendario"
L["WN7_2_TEXT"] = "El calendario es un pequeño cuadrado junto al nombre de zona; ponlo en el anillo o detrás del icono de día y noche en Botón del calendario de las opciones. Marca Calendario en Minimapa de Ventanas de ClassicUI Forever en el modo edición para moverlo o redimensionarlo."
L["WN6_1_TITLE"] = "Botón del calendario"
L["WN6_1_TEXT"] = "El calendario está bajo el icono de día y noche del minimapa. Para ocultarlo, desmarca Botón del calendario en Minimapa de las opciones."
L["WN5_1_TITLE"] = "Correcciones"
L["WN5_1_TEXT"] = "La marca de jugadores nuevos bienvenidos del buscador de grupos se alinea con los iconos de rol. Detalles en el registro de cambios completo."
L["WN4_1_TITLE"] = "Correcciones"
L["WN4_1_TEXT"] = "Las pestañas toman el ratón en la propia pestaña, una profesión lanzada desde el libro de hechizos cierra el libro en combate, y la cabecera de la ventana de botín queda limpia. Detalles en el registro de cambios completo."
L["WN3_1_TITLE"] = "Piezas de la barra clásica"
L["WN3_1_TEXT"] = "Classic no tenía botón de profesiones ni bolsa de componentes, así que el botón de profesiones sale del micromenú (las profesiones se abren desde el libro de hechizos) y la bolsa de componentes es un pequeño botón redondo al pasar el ratón. Las barras 2 y 3 vuelven a caber entre los grifos. Ambas son filas en Barra clásica de las opciones."
L["WN2_1_TITLE"] = "Modo edición de ventanas"
L["WN2_1_TEXT"] = "Marca Ventanas en el modo edición para mover y redimensionar la ficha de personaje, el libro de hechizos, los talentos, el registro de misiones, las profesiones y el mapa."
L["WN2_2_TITLE"] = "Perfiles"
L["WN2_2_TEXT"] = "Una pestaña Perfiles en las opciones guarda ajustes con nombre por personaje."
L["WN2_3_TITLE"] = "Bronce u Oscuro"
L["WN2_3_TEXT"] = "El tema personalizado viene en el bronce de Forever o en un antracita oscuro. Mira la opción Tema personalizado."
L["WN2_4_TITLE"] = "Barra clásica"
L["WN2_4_TEXT"] = "Las barras ya no se reducen por defecto. La barra lleva ahora la barra de latencia, el llavero y la bolsa de componentes como en clásico; cada uno se puede mover en el modo edición u ocultar en Barra clásica de las opciones."
L["WN2_5_TITLE"] = "Botones del minimapa"
L["WN2_5_TEXT"] = "Los botones de minimapa de otros accesorios pueden agruparse tras un botón en el anillo. Mira la opción Agrupar botones de accesorios."
L["WN2_6_TITLE"] = "Opciones"
L["WN2_6_TEXT"] = "Secciones de Misiones y Mapa, y filas nuevas para el marco del mapa, la ventana de botín, las tiradas de botín, ocultar el seguimiento del juego, el botón de profesiones y el texto de teclas."
L["WN2_7_TITLE"] = "Restablecer diseño clásico"
L["WN2_7_TEXT"] = "Devuelve de una vez las ventanas, el seguimiento, los grifos, las piezas de barra y los ajustes de diseño."
